import java.util.*;

enum Kind { TOOL, SEED }

interface Stockable {
    String name();
    int kg();
    default boolean heavy() { return kg() > 20; }
}

record Tool(String name, int kg) implements Stockable { }
record Seed(String name, int kg, Kind kind) implements Stockable { }

class StoreFullException extends Exception {
    StoreFullException(String what) { super("No space for " + what); }
}

public class Example {
    static final int LIMIT = 50;
    static final List<Stockable> store = new ArrayList<>();

    static void add(Stockable s) throws StoreFullException {
        int used = 0;
        for (Stockable x : store) used += x.kg();
        if (used + s.kg() > LIMIT) throw new StoreFullException(s.name());
        store.add(s);
    }

    public static void main(String[] args) {
        try {
            add(new Tool("Hoe", 3));
            add(new Seed("Maize", 25, Kind.SEED));
            add(new Seed("Beans", 30, Kind.SEED));
        } catch (StoreFullException e) {
            System.out.println(e.getMessage());
        }
        store.sort(Comparator.comparingInt(Stockable::kg).reversed().thenComparing(Stockable::name));
        for (Stockable s : store) System.out.println(s.name() + (s.heavy() ? " (heavy)" : ""));
    }
}

