enum Rarity {
    COMMON(1), RARE(3), LEGENDARY(10);
    private final int multiplier;
    Rarity(int multiplier) { this.multiplier = multiplier; }
    int multiplier() { return multiplier; }
}

interface Item {
    String name();
    int weight();
    Rarity rarity();
    int baseValue();
    default int value() { return baseValue() * rarity().multiplier(); }
}

record Weapon(String name, int weight, Rarity rarity, int baseValue, int damage) implements Item {
    Weapon { Loot.require(name, weight); }
}

record Potion(String name, int weight, Rarity rarity, int baseValue, int heal) implements Item {
    Potion { Loot.require(name, weight); }
}

record Gem(String name, int weight, Rarity rarity, int baseValue) implements Item {
    Gem { Loot.require(name, weight); }
}

public class Loot {
    // Shared checks for every kind of item.
    static void require(String name, int weight) {
        if (name == null || name.isBlank()) throw new IllegalArgumentException("item needs a name");
        if (weight < 0) throw new IllegalArgumentException("weight can't be negative");
    }

    public static String describe(Item item) {
        if (item instanceof Weapon w) return w.name() + " (" + w.damage() + " dmg, " + w.value() + " gold)";
        if (item instanceof Potion p) return p.name() + " (+" + p.heal() + " hp, " + p.value() + " gold)";
        return item.name() + " (" + item.value() + " gold)";
    }
}

