import java.util.*;

interface Item {
    String name();
    int weight();
    int value();
}

record Weapon(String name, int weight, int value, int damage) implements Item { }
record Potion(String name, int weight, int value, int heal) implements Item { }

// Checked: the game must decide what to do when the bag is full.
class InventoryFullException extends Exception {
    InventoryFullException(String item, int over) {
        super("No room for " + item + ": " + over + " kg over");
    }
}

public class Inventory {
    public static final Comparator<Item> BY_VALUE =
        Comparator.comparingInt(Item::value).reversed().thenComparing(Item::name);

    private final int maxWeight;
    private final List<Item> items = new ArrayList<>();

    public Inventory(int maxWeight) {
        if (maxWeight <= 0) throw new IllegalArgumentException("maxWeight must be positive");
        this.maxWeight = maxWeight;
    }

    public void add(Item item) throws InventoryFullException {
        int after = totalWeight() + item.weight();
        if (after > maxWeight) throw new InventoryFullException(item.name(), after - maxWeight);
        items.add(item);
    }

    public int totalWeight() {
        int w = 0;
        for (Item i : items) w += i.weight();
        return w;
    }

    public int totalValue() {
        int v = 0;
        for (Item i : items) v += i.value();
        return v;
    }

    public Item remove(String name) {
        for (Iterator<Item> it = items.iterator(); it.hasNext(); ) {
            Item i = it.next();
            if (i.name().equalsIgnoreCase(name)) {
                it.remove();
                return i;
            }
        }
        return null;
    }

    public List<Item> sortedBy(Comparator<Item> order) {
        List<Item> copy = new ArrayList<>(items);
        copy.sort(order);
        return copy;
    }

    // Generic: ofType(Weapon.class) gives a List<Weapon>, no casts for the caller.
    public <T extends Item> List<T> ofType(Class<T> type) {
        List<T> out = new ArrayList<>();
        for (Item i : items) if (type.isInstance(i)) out.add(type.cast(i));
        return out;
    }
}

