import java.util.*;
import java.util.function.Function;

record Loot(String name, int value) { }

public class Ranking {
    public static List<Loot> rank(List<Loot> items) {
        List<Loot> copy = new ArrayList<>(items);
        copy.sort(Comparator.comparingInt(Loot::value).reversed().thenComparing(Loot::name));
        return copy;
    }

    public static boolean checkRanking(Function<List<Loot>, List<Loot>> ranker) {
        try {
            // Ties on purpose, in the wrong name order, so a missing tie-breaker shows.
            List<Loot> input = new ArrayList<>(List.of(
                new Loot("Ruby", 50), new Loot("Bow", 20), new Loot("Opal", 50), new Loot("Axe", 20)));
            List<Loot> before = new ArrayList<>(input);
            List<Loot> expected = List.of(
                new Loot("Opal", 50), new Loot("Ruby", 50), new Loot("Axe", 20), new Loot("Bow", 20));

            List<Loot> result = ranker.apply(input);
            if (!expected.equals(result)) return false;   // order, ties, nothing lost
            if (!before.equals(input)) return false;      // the caller's list is untouched

            List<Loot> empty = ranker.apply(new ArrayList<>());
            return empty != null && empty.isEmpty();
        } catch (RuntimeException e) {
            return false;   // crashing is a bug too
        }
    }
}
